public class MainActivity extends Activity {
  final int BG=0xff080d18, CARD=0xff142035, CARD2=0xff1d3046, MINT=0xff55e2c1, MUTED=0xffa8b6c9, WHITE=0xfff5f7fb;
  final ExecutorService io=Executors.newSingleThreadExecutor();
  final ArrayList<Item> live=new ArrayList<>(), movies=new ArrayList<>(), series=new ArrayList<>(), favorites=new ArrayList<>(), recent=new ArrayList<>();
  SharedPreferences prefs; LinearLayout root,listing; EditText urlField,userField,passField,macField; TextView status; ExoPlayer player; PlayerView playerView; boolean busy=false;
  static class Item {String name,url,group,logo,type;Item(String n,String u,String g,String l,String t){name=n;url=u;group=g;logo=l;type=t;}}
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("zyphoryx",0);player=new ExoPlayer.Builder(this).build();restore();home();}
  int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
  LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
  LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
  TextView text(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setGravity(Gravity.CENTER_VERTICAL);return t;}
  GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
  TextView action(String s,Runnable r){TextView t=text(s,15,WHITE);t.setGravity(Gravity.CENTER);t.setPadding(dp(12),dp(10),dp(12),dp(10));t.setBackground(shape(CARD2,14));t.setFocusable(true);t.setClickable(true);t.setOnFocusChangeListener((v,f)->t.setBackground(shape(f?0xff2a5362:CARD2,14)));t.setOnClickListener(v->r.run());return t;}
  void page(String title){root=col();root.setPadding(dp(20),dp(14),dp(20),dp(20));root.setBackgroundColor(BG);ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.addView(root);setContentView(sc);LinearLayout top=row();TextView mark=text("Z",25,MINT);mark.setGravity(Gravity.CENTER);mark.setTypeface(null,Typeface.BOLD);mark.setBackground(shape(CARD2,14));top.addView(mark,lp(46,46));LinearLayout brand=col();brand.setPadding(dp(12),0,0,0);brand.addView(text("ZYPHORYX",14,MINT));brand.addView(text("IPTV PLAYER",10,MUTED));top.addView(brand,new LinearLayout.LayoutParams(0,dp(46),1));top.addView(action("⌂ الرئيسية",()->home()),lp(-2,44));root.addView(top,lp(-1,50));TextView h=text(title,28,WHITE);h.setTypeface(null,Typeface.BOLD);h.setPadding(0,dp(17),0,dp(3));root.addView(h);root.addView(text("تجربة مشاهدة مصممة للهاتف والتلفاز",13,MUTED),lp(-1,28));}
  void gap(int h){root.addView(new View(this),lp(1,h));}
  void home(){page("مساحتك للمشاهدة");LinearLayout hero=col();hero.setPadding(dp(22),dp(22),dp(22),dp(22));hero.setBackground(shape(0xff142c3b,22));hero.addView(text("كل مكتبتك في مكان واحد",23,WHITE));hero.addView(text("بث مباشر، أفلام، مسلسلات ومفضلة",14,MUTED),lp(-1,36));hero.addView(action("＋  إضافة مصدر IPTV",()->sources()),lp(-1,54));root.addView(hero,lp(-1,-2));gap(16);
    LinearLayout stats=row();stats.addView(stat("مباشر",live.size()),new LinearLayout.LayoutParams(0,dp(88),1));stats.addView(stat("أفلام",movies.size()),new LinearLayout.LayoutParams(0,dp(88),1));stats.addView(stat("مسلسلات",series.size()),new LinearLayout.LayoutParams(0,dp(88),1));root.addView(stats,lp(-1,94));gap(15);root.addView(text("استكشف",19,WHITE));gap(7);
    LinearLayout r1=row();r1.addView(action("◉  البث المباشر",()->library("live")),new LinearLayout.LayoutParams(0,dp(58),1));r1.addView(action("▣  الأفلام",()->library("movies")),new LinearLayout.LayoutParams(0,dp(58),1));r1.addView(action("▤  المسلسلات",()->library("series")),new LinearLayout.LayoutParams(0,dp(58),1));root.addView(r1,lp(-1,64));gap(8);
    LinearLayout r2=row();r2.addView(action("★ المفضلة",()->library("favorites")),new LinearLayout.LayoutParams(0,dp(54),1));r2.addView(action("◷ آخر المشاهدات",()->library("recent")),new LinearLayout.LayoutParams(0,dp(54),1));r2.addView(action("⚙ الإعدادات",()->settings()),new LinearLayout.LayoutParams(0,dp(54),1));root.addView(r2,lp(-1,60));gap(18);root.addView(text(prefs.getString("sourceLabel","لم تتم إضافة مصدر بعد"),13,MINT));root.addView(text("المشغّل لا يتضمن قنوات أو اشتراكات. أضف مصدراً تملك حق استخدامه.",12,MUTED));}
  View stat(String label,int n){LinearLayout c=col();c.setPadding(dp(12),dp(10),dp(12),dp(8));c.setBackground(shape(CARD,14));c.addView(text(label,12,MUTED));TextView v=text(""+n,25,WHITE);v.setTypeface(null,Typeface.BOLD);c.addView(v);return c;}
  EditText field(String hint,String key){EditText e=new EditText(this);e.setSingleLine(true);e.setTextColor(WHITE);e.setHintTextColor(MUTED);e.setHint(hint);e.setPadding(dp(13),0,dp(13),0);e.setBackground(shape(CARD,12));e.setText(prefs.getString(key,""));LinearLayout.LayoutParams p=lp(-1,50);p.bottomMargin=dp(9);root.addView(e,p);return e;}
  void sources(){page("إضافة مصدر");root.addView(text("طريقة الاتصال",15,WHITE));Spinner kind=new Spinner(this);kind.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"M3U / M3U8","Xtream Codes","Stalker Portal (تجريبي)"}));kind.setSelection(prefs.getInt("kind",0));root.addView(kind,lp(-1,48));gap(8);urlField=field("رابط القائمة أو عنوان الخادم","address");userField=field("اسم المستخدم (Xtream)","user");passField=field("كلمة المرور (Xtream)","pass");passField.setInputType(129);macField=field("MAC Address (Stalker)","mac");root.addView(action("اتصال وتحميل المكتبة",()->load(kind.getSelectedItemPosition())),lp(-1,54));gap(8);status=text("تُحفظ بياناتك محلياً على هذا الجهاز.",13,MINT);root.addView(status,lp(-1,40));root.addView(action("رجوع",()->home()),lp(-1,48));}
  String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
  String request(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(16000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","Zyphoryx/0.1");try{int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)throw new IOException("HTTP "+code);try(InputStream src=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=src.read(b))!=-1)out.write(b,0,n);String s=out.toString("UTF-8");if(code>=400)throw new IOException("HTTP "+code);return s;}}finally{c.disconnect();}}
  void load(int kind){if(busy)return;String address=urlField.getText().toString().trim(),u=userField.getText().toString().trim(),p=passField.getText().toString(),mac=macField.getText().toString().trim();if(address.isEmpty()){status.setText("أدخل عنوان المصدر أولاً.");return;}busy=true;status.setText("جارٍ الاتصال وتحليل المكتبة…");io.execute(()->{try{ArrayList<Item> l=new ArrayList<>(),m=new ArrayList<>(),s=new ArrayList<>();if(kind==0)l.addAll(parseM3u(address));else if(kind==1){if(u.isEmpty()||p.isEmpty())throw new Exception("أدخل اسم المستخدم وكلمة المرور");String base=address.replaceAll("/+$","");JSONObject auth=new JSONObject(request(base+"/player_api.php?username="+enc(u)+"&password="+enc(p)));JSONObject ui=auth.optJSONObject("user_info");if(ui!=null&&ui.optInt("auth",1)==0)throw new Exception("بيانات الدخول غير صحيحة");l.addAll(xtream(base,u,p,"get_live_streams","live"));m.addAll(xtream(base,u,p,"get_vod_streams","movie"));s.addAll(xtream(base,u,p,"get_series","series"));}else throw new Exception("Stalker يحتاج محولاً خاصاً لكل نوع بوابة؛ لم أعتبره مدعوماً قبل اختباره.");runOnUiThread(()->{busy=false;live.clear();live.addAll(l);movies.clear();movies.addAll(m);series.clear();series.addAll(s);prefs.edit().putInt("kind",kind).putString("address",address).putString("user",u).putString("pass",p).putString("mac",mac).putString("sourceLabel",kind==0?"M3U • "+host(address):"Xtream • "+u).apply();save();home();Toast.makeText(this,"تم تحميل "+(l.size()+m.size()+s.size())+" عنصر",Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->{busy=false;if(status!=null)status.setText("تعذر الاتصال: "+(e.getMessage()==null?"خطأ غير معروف":e.getMessage()));});}});}
  String host(String u){try{return URI.create(u).getHost();}catch(Exception e){return "قائمة";}}
  String attr(String l,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile(key+"=\"([^\"]*)\"").matcher(l);return m.find()?m.group(1):"";}
  ArrayList<Item> parseM3u(String url)throws Exception{String body=request(url);ArrayList<Item> out=new ArrayList<>();String name="قناة",group="غير مصنف",logo="";for(String raw:body.replace("\ufeff","").split("\\r?\\n")){String line=raw.trim();if(line.startsWith("#EXTINF")){int comma=line.lastIndexOf(',');name=comma>=0?line.substring(comma+1).trim():attr(line,"tvg-name");group=attr(line,"group-title");logo=attr(line,"tvg-logo");if(group.isEmpty())group="غير مصنف";}else if(!line.isEmpty()&&!line.startsWith("#")){try{if(!line.matches("(?i)^[a-z][a-z0-9+.-]*://.*"))line=new URL(new URL(url),line).toString();}catch(Exception ignored){}if(line.matches("(?i)^(https?|rtsp|rtmp|udp)://.*"))out.add(new Item(name,line,group,logo,"live"));name="قناة";group="غير مصنف";logo="";}}if(out.isEmpty())throw new Exception("لا توجد روابط M3U صالحة");return out;}
  ArrayList<Item> xtream(String base,String u,String p,String action,String type)throws Exception{String json=request(base+"/player_api.php?username="+enc(u)+"&password="+enc(p)+"&action="+action);JSONArray a=new JSONArray(json);ArrayList<Item> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString(type.equals("series")?"series_id":"stream_id");String url=type.equals("movie")?base+"/movie/"+enc(u)+"/"+enc(p)+"/"+id+"."+o.optString("container_extension","mp4"):type.equals("series")?base+"/series/"+enc(u)+"/"+enc(p)+"/"+id:base+"/live/"+enc(u)+"/"+enc(p)+"/"+id+"."+o.optString("container_extension","ts");out.add(new Item(o.optString("name","بدون اسم"),url,o.optString("category_name","غير مصنف"),o.optString(type.equals("series")?"cover":"stream_icon",""),type));}return out;}
  ArrayList<Item> data(String type){return type.equals("live")?live:type.equals("movies")?movies:type.equals("series")?series:type.equals("favorites")?favorites:recent;}
  String title(String type){return type.equals("live")?"البث المباشر":type.equals("movies")?"الأفلام":type.equals("series")?"المسلسلات":type.equals("favorites")?"المفضلة":"آخر المشاهدات";}
  void library(String type){ArrayList<Item> data=data(type);page(title(type));LinearLayout filters=row();EditText search=new EditText(this);search.setSingleLine(true);search.setHint("ابحث بالاسم أو المجموعة");search.setHintTextColor(MUTED);search.setTextColor(WHITE);search.setPadding(dp(12),0,dp(12),0);search.setBackground(shape(CARD,12));filters.addView(search,new LinearLayout.LayoutParams(0,dp(48),1));Spinner groups=new Spinner(this);ArrayList<String> gs=new ArrayList<>();gs.add("كل المجموعات");for(Item i:data)if(i.group!=null&&!i.group.isEmpty()&&!gs.contains(i.group))gs.add(i.group);groups.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,gs));filters.addView(groups,lp(140,48));root.addView(filters,lp(-1,54));if(type.equals("live")){playerView=new PlayerView(this);playerView.setPlayer(player);playerView.setUseController(true);root.addView(playerView,lp(-1,220));}listing=col();root.addView(listing,lp(-1,-2));Runnable render=()->{listing.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT),g=String.valueOf(groups.getSelectedItem());int n=0;for(Item item:new ArrayList<>(data)){if(!item.name.toLowerCase(Locale.ROOT).contains(q)&&!String.valueOf(item.group).toLowerCase(Locale.ROOT).contains(q))continue;if(!g.equals("كل المجموعات")&&!g.equals(item.group))continue;LinearLayout tile=row();tile.setPadding(dp(10),dp(6),dp(10),dp(6));tile.setBackground(shape(CARD,12));LinearLayout info=col();info.addView(text(item.name,15,WHITE));info.addView(text(item.group,12,MUTED));tile.addView(info,new LinearLayout.LayoutParams(0,dp(52),1));tile.addView(action("▶",()->play(item)),lp(44,42));tile.addView(action(fav(item)?"★":"☆",()->{toggle(item);library(type);}),lp(44,42));LinearLayout.LayoutParams p=lp(-1,66);p.bottomMargin=dp(6);listing.addView(tile,p);tile.setFocusable(true);tile.setOnClickListener(v->play(item));n++;}if(n==0)listing.addView(text(data.isEmpty()?"لا توجد عناصر بعد — أضف مصدراً صالحاً.":"لا توجد نتائج مطابقة.",14,MUTED));};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render.run();}public void afterTextChanged(Editable e){}});groups.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){render.run();}});render.run();gap(10);root.addView(action("＋ إضافة مصدر",()->sources()),lp(-1,48));}
  boolean fav(Item a){for(Item i:favorites)if(i.url.equals(a.url))return true;return false;}
  void toggle(Item a){if(fav(a))removeUrl(favorites,a.url);else favorites.add(a);save();}
  void play(Item i){try{player.setMediaItem(MediaItem.fromUri(Uri.parse(i.url)));player.prepare();player.play();removeUrl(recent,i.url);recent.add(0,i);while(recent.size()>40)recent.remove(recent.size()-1);save();}catch(Exception e){Toast.makeText(this,"تعذر تشغيل هذا الرابط",Toast.LENGTH_SHORT).show();}}
  void settings(){page("الإعدادات");root.addView(text("المكتبة والمفضلة محفوظة محلياً.",14,MUTED));root.addView(action("تغيير مصدر IPTV",()->sources()),lp(-1,52));gap(8);root.addView(action("مسح المكتبة",()->new AlertDialog.Builder(this).setTitle("مسح المكتبة؟").setMessage("سيتم حذف القنوات والأفلام والمسلسلات والمفضلة المحفوظة.").setNegativeButton("إلغاء",null).setPositiveButton("مسح",(d,w)->{live.clear();movies.clear();series.clear();favorites.clear();recent.clear();save();home();}).show()),lp(-1,52));gap(14);root.addView(text("Zyphoryx IPTV • 0.1.0",13,MINT));root.addView(text("حدود النسخة الأولية: لا يوجد EPG بعد، وتشغيل حلقات المسلسلات يحتاج جلب تفاصيل الحلقات من الخادم. Stalker لم يُعلن دعمه قبل اختباره على بوابات حقيقية.",12,MUTED));}
  String readUtf8(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}
  void removeUrl(ArrayList<Item> list,String url){for(int n=list.size()-1;n>=0;n--)if(list.get(n).url.equals(url))list.remove(n);}
  void save(){try{JSONObject o=new JSONObject();put(o,"live",live);put(o,"movies",movies);put(o,"series",series);put(o,"favorites",favorites);put(o,"recent",recent);try(FileOutputStream f=openFileOutput("library.json",0)){f.write(o.toString().getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
  void put(JSONObject root,String k,ArrayList<Item> list)throws Exception{JSONArray a=new JSONArray();for(Item i:list){JSONObject o=new JSONObject();o.put("n",i.name);o.put("u",i.url);o.put("g",i.group);o.put("l",i.logo);o.put("t",i.type);a.put(o);}root.put(k,a);}
  void restore(){try(InputStream in=openFileInput("library.json")){JSONObject o=new JSONObject(readUtf8(in));read(o,"live",live);read(o,"movies",movies);read(o,"series",series);read(o,"favorites",favorites);read(o,"recent",recent);}catch(Exception ignored){}}
  void read(JSONObject o,String k,ArrayList<Item> list){JSONArray a=o.optJSONArray(k);if(a==null)return;for(int n=0;n<a.length();n++){JSONObject x=a.optJSONObject(n);if(x!=null)list.add(new Item(x.optString("n"),x.optString("u"),x.optString("g"),x.optString("l"),x.optString("t")));}}
  @Override public void onBackPressed(){home();}
  @Override protected void onDestroy(){super.onDestroy();if(player!=null)player.release();io.shutdownNow();}
}
